/**
 * Pre-baked anti-aliased Segoe UI Bold glyph atlas (26px, 40px, 56px) for zero-dependency 1200x630 OG PNG generation.
 */
import zlib from 'node:zlib';

const PACKED_ATLAS_B64 = "";

let _cachedAtlas = null;

export function getOgFontAtlas() {
  if (_cachedAtlas) return _cachedAtlas;
  const jsonStr = zlib.inflateSync(Buffer.from(PACKED_ATLAS_B64, 'base64')).toString('utf8');
  const parsed = JSON.parse(jsonStr);
  const compiled = {};
  for (const [key, sz] of Object.entries(parsed)) {
    const map = new Map();
    for (const [cp, adv, xOff, yOff, w, h, alphaB64] of sz.glyphs) {
      map.set(cp, {
        adv,
        xOff,
        yOff,
        w,
        h,
        alpha: alphaB64 ? Buffer.from(alphaB64, 'base64') : null
      });
    }
    compiled[key] = {
      px: sz.px,
      lineHeight: sz.lineHeight,
      map,
      spaceAdv: (map.get(32) && map.get(32).adv) || Math.round(sz.px * 0.3)
    };
  }
  _cachedAtlas = compiled;
  return _cachedAtlas;
}
